import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.CdjpmwdR.js";const o="/assets/image-1.BZojNKVT.png",s="/assets/image-2.DU_0Fs-4.png",r="/assets/image-3.DFogVQnE.png",p="/assets/image-main.QAIGTop_.png",P=JSON.parse('{"title":"AI Powered PKM：从笔记中心到任务中心","description":"本文复盘我将 AI 融入 Mesh-Shaped PKM 的过程，重点展示如何把“知识整理”转为“任务驱动”，并通过反馈闭环持续提升执行效率。","frontmatter":{"category":"domain","date":"2024-12-01","title":"AI Powered PKM：从笔记中心到任务中心","description":"本文复盘我将 AI 融入 Mesh-Shaped PKM 的过程，重点展示如何把“知识整理”转为“任务驱动”，并通过反馈闭环持续提升执行效率。","tags":["domain","PKM","logseq"],"image":"/blogs/assets/202412-ai-powered-pkm/image-1.png"},"headers":[],"relativePath":"blogs/2024/202412-ai-powered-pkm.md","filePath":"blogs/2024/202412-ai-powered-pkm.md"}'),n={name:"blogs/2024/202412-ai-powered-pkm.md"};function d(m,l,g,u,c,h){return i(),a("div",null,[...l[0]||(l[0]=[t('<p>从 2022 年开始使用 Logseq 到现在，我的 <a href="./../2022/202212-logseq-pkm">Mesh-Shaped 知识管理模式</a> 已经相对稳定。最近一年引入 AI 后，系统的重心发生了变化：从“更好地记录知识”转向“更快地完成任务”。</p><h2 id="ai-powered" tabindex="-1">AI Powered <a class="header-anchor" href="#ai-powered" aria-label="Permalink to &quot;AI Powered&quot;">​</a></h2><p>最大的变化是输入成本显著下降。在旧流程里：</p><ul><li>需要通过多种工具来收集信息，包括任务、稍后阅读、知识等</li><li>需要在Logseq中进行信息初筛，任务规划，以确定哪些是闪念、哪些是需要深入学习的知识、哪些是任务</li><li>需要在Logseq中存储和分类大量的笔记，建立双链</li><li>需要定期整理、总结、精炼</li></ul><p>有了 AI 之后，我几乎没有再复制过超过200字的文本，也没有再添加过超过10张图片或是超链接。你可以仅保存一个AI的会话链接，或是一段Prompt，就可以得到超过1000字的回答。</p><p>因此我重新构建了我的工作流，并将AI显式化的嵌入到各个流程内。</p><h2 id="任务驱动" tabindex="-1">任务驱动 <a class="header-anchor" href="#任务驱动" aria-label="Permalink to &quot;任务驱动&quot;">​</a></h2><p>我将我的工作流程分为了三个部分：</p><ul><li><strong>任务驱动：“飞轮”系统</strong><ul><li>飞轮系统是一种更宏观的目标管理方法，它侧重于长期愿景和持续的进步：</li><li>愿景：设定一个长远的愿景或目标，这个目标可能并不具体，但提供了方向。</li><li>行动：在执行过程中，通过不断的尝试和调整，逐步接近愿景。</li><li>反馈：从行动中获得反馈，这些反馈可能会产生新的GTD任务或是调整飞轮任务。</li><li>迭代：根据反馈不断调整行动计划，以确保持续向愿景靠近。</li></ul></li></ul><p><img src="'+o+'" alt="alt text"></p><ul><li><strong>任务执行：GTD 系统</strong><ul><li>GTD系统强调的是任务的明确性和可操作性，它要求任务有明确的目标和步骤</li><li>收集：将所有任务和想法收集到一个“收集箱”中，以便不会忘记任何事情。</li><li>处理：对收集到的任务进行快速处理，决定是立即执行、委派、延迟还是删除。</li><li>组织：将任务分类并放入不同的“篮子”中，比如等待清单、项目清单、日程表等。</li><li>回顾：定期回顾任务清单，确保所有任务都得到适当的关注。</li><li>执行：根据优先级和可用时间执行任务。</li></ul></li></ul><p><img src="'+s+'" alt="alt text"></p><ul><li><strong>获得反馈</strong><ul><li>输出型反馈，写文留存</li><li>输入性反馈，新任务</li></ul></li></ul><p><img src="'+r+'" alt="alt text"></p><blockquote><p>所有事务都以任务形式存在，比如读一本书、尝试一个工具，并配置对应反馈机制，形成持续迭代。</p><p>过去 PKM 往往以笔记为中心，重在收集与整理。AI 加入后，真正的瓶颈不再是“存不下”，而是“做不完”。因此系统应转向任务驱动，以价值交付为核心。</p></blockquote><p><img src="'+p+'" alt="alt text"></p><blockquote><p>可以看到，AI 可以在目标管理、任务拆解、任务执行（信息收集、整理、编码）等多个环节中发挥作用，从而提高工作效率。</p></blockquote><h2 id="工具使用" tabindex="-1">工具使用 <a class="header-anchor" href="#工具使用" aria-label="Permalink to &quot;工具使用&quot;">​</a></h2><p>我主要会用到以下 AI 工具：</p><ul><li>Copilot：代码、文档、博客编写（处理所有在VSCode里完成的任务）</li><li>Logseq AI Assistant 插件：处理所有Logseq内的任务，代替人工的总结、翻译、tag、任务拆分、OKR &amp; Retro ...</li><li>Kimi：闪念和稍后阅读 <ul><li>免费，且全平台可用（App、微信、Web）</li><li>所有的想法和链接我都会先丢给 Kimi <ul><li>可以获得即时的反馈，比如一个问题的答案、一篇文章的摘要、一张图片的描述</li><li>可以保存会话链接来“保存”这个想法，以便后续进一步处理</li></ul></li><li>对于有价值的内容，仅需要将会话链接保存到Logseq中，加上少量的描述和tag即可</li></ul></li></ul><h2 id="随想" tabindex="-1">随想 <a class="header-anchor" href="#随想" aria-label="Permalink to &quot;随想&quot;">​</a></h2><h3 id="传统知识管理的边际收益在下降" tabindex="-1">传统知识管理的边际收益在下降 <a class="header-anchor" href="#传统知识管理的边际收益在下降" aria-label="Permalink to &quot;传统知识管理的边际收益在下降&quot;">​</a></h3><p>原本的 Knowledge Management 也是为了解决信息过载的问题，利用软件（页、块、tag）建立索引，以便快速找到需要的信息。但随着 AI 技术的发展，索引变成了Prompt，信息变成了AI的回答并且存储在云端。</p><p>PKM 的目标始终是提升执行效率。AI 让我们可以把更多精力放在决策与行动，而不是信息搬运。因此，新一代 PKM 更应围绕任务推进与反馈闭环来设计。</p>',24)])])}const A=e(n,[["render",d]]);export{P as __pageData,A as default};
